function __be(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function __beNum(n) {
  const v = Number(n);
  return isFinite(v) ? String(Math.round(v)) : '0';
}

